from langchain.chat_models import ChatOpenAI
from langchain.schema import HumanMessage, AIMessage, SystemMessage, ToolMessage
from tools import web_search, calculator

TOOLS = {
    'web_search': web_search,
    'calculator': calculator,
}

TOOL_SCHEMAS = [
    {
        'type': 'function',
        'function': {
            'name': 'web_search',
            'description': 'Search the web for current information',
            'parameters': {
                'type': 'object',
                'properties': {'query': {'type': 'string', 'description': 'Search query'}},
                'required': ['query'],
            },
        },
    },
    {
        'type': 'function',
        'function': {
            'name': 'calculator',
            'description': 'Evaluate a mathematical expression safely',
            'parameters': {
                'type': 'object',
                'properties': {'expression': {'type': 'string', 'description': 'Math expression to evaluate'}},
                'required': ['expression'],
            },
        },
    },
]

MAX_ITERATIONS = 10  # Hard limit: prevents infinite loops and runaway API spend


def run_agent(user_query: str) -> str:
    """Run the tool-calling agent loop with safety limits.

    Bug fixes applied:
    1. Added MAX_ITERATIONS guard — the loop now exits with a fallback answer
       if the model has not produced a final response after 10 rounds.
    2. Tool results are appended as ToolMessage (role='tool') with the correct
       tool_call_id — without this, the model cannot match results to calls
       and re-calls the same tool indefinitely.
    """
    llm = ChatOpenAI(model='gpt-4o', temperature=0)

    messages = [
        SystemMessage(content='You are a helpful assistant. Use tools when needed.'),
        HumanMessage(content=user_query),
    ]

    for iteration in range(MAX_ITERATIONS):
        response = llm.invoke(messages, tools=TOOL_SCHEMAS)

        if not response.tool_calls:
            # Model produced a final text response — we're done.
            return response.content

        # Append the AI response (which includes tool_calls metadata)
        messages.append(response)

        for tool_call in response.tool_calls:
            tool_name = tool_call['name']
            tool_args = tool_call['args']

            if tool_name not in TOOLS:
                # Unknown tool — append an error result so the model can recover
                error_result = f'Error: tool "{tool_name}" is not available.'
                messages.append(
                    ToolMessage(content=error_result, tool_call_id=tool_call['id'])
                )
                continue

            try:
                result = TOOLS[tool_name](**tool_args)
            except Exception as e:
                result = f'Tool execution error: {e}'

            # CRITICAL: role must be 'tool' and tool_call_id must match
            # the originating tool call. Using HumanMessage here breaks the
            # conversation structure — the LLM cannot correlate the result
            # to the call and will re-invoke the same tool in a loop.
            messages.append(
                ToolMessage(content=str(result), tool_call_id=tool_call['id'])
            )

    # Exceeded MAX_ITERATIONS — return a safe fallback rather than hanging
    return 'I was unable to complete this task within the allowed number of steps. Please try rephrasing your question.'
